"use strict";(globalThis.webpackChunkcodeeatcode_github_io=globalThis.webpackChunkcodeeatcode_github_io||[]).push([[2896],{2536(e,t,a){a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>c,frontMatter:()=>s,metadata:()=>i,toc:()=>h});var i=a(3102),n=a(6070),r=a(5589);const s={title:"What to leave out of an architecture diagram",slug:"the-art-of-the-architecture-diagram-is-knowing-what-to-leave-out",date:new Date("2026-05-21T07:00:00.000Z"),authors:["ambersariya"],tags:["architecture","diagrams","c4","d2"],last_updated:new Date("2026-11-20T10:31:14.000Z")},o=void 0,l={authorsImageUrls:[void 0]},h=[{value:"What question does the diagram answer?",id:"what-question-does-the-diagram-answer",level:2},{value:"Give AI tools the same brief",id:"give-ai-tools-the-same-brief",level:2}];function d(e){const t={a:"a",h2:"h2",img:"img",p:"p",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.p,{children:"There's a particular type of diagram that engineers love producing and nobody can read. Boxes for every service, arrows for every dependency, and a legend that requires its own legend. The details may all be accurate, but you still can't tell what the system does."}),"\n",(0,n.jsx)(t.p,{children:"A useful architecture diagram answers a question for its reader. Deciding what to leave out is part of that job."}),"\n",(0,n.jsxs)(t.p,{children:["I've been doing ",(0,n.jsx)(t.a,{href:"https://c4model.com/diagrams",children:"C4 modelling"})," for a while, and that's what I like about it. System Context, Container, Component, Code: four levels of detail for different questions and audiences. Mixing those levels makes it harder to see what a diagram is trying to explain."]}),"\n",(0,n.jsxs)(t.p,{children:["The tooling has been a headache. I tried a few diagram-as-code options that seemed to get in the way more than they helped. I've recently switched to ",(0,n.jsx)(t.a,{href:"https://d2lang.com/",children:"D2"}),", and it's been noticeably better for me. The syntax is small, the output is clean, and I can spend more time on what the diagram needs to say."]}),"\n",(0,n.jsx)(t.h2,{id:"what-question-does-the-diagram-answer",children:"What question does the diagram answer?"}),"\n",(0,n.jsx)(t.p,{children:"Engineers instinctively want to put everything in. Every dependency. Every call. Every integration they personally wired up at 11pm on a Thursday and feel a certain proprietary affection for."}),"\n",(0,n.jsx)(t.p,{children:"Those details can matter. If you're debugging how a chat request moves through the system, protocols, authentication and session storage are relevant:"}),"\n",(0,n.jsx)(t.img,{src:"/d2/blog/the-art-of-the-architecture-diagram-is-knowing-what-to-leave-out/0.svg",alt:"d2 diagram"}),"\n",(0,n.jsx)(t.p,{children:'But if someone asks, "What are the main parts of this chat application?", the request-level detail gets in the way. A simpler view helps:'}),"\n",(0,n.jsx)(t.img,{src:"/d2/blog/the-art-of-the-architecture-diagram-is-knowing-what-to-leave-out/1.svg",alt:"d2 diagram"}),"\n",(0,n.jsx)(t.p,{children:"The first view helps trace a request. The second shows the broad responsibilities: the web app sends messages to an API, which calls a language-model provider and stores conversations."}),"\n",(0,n.jsxs)(t.p,{children:["These are illustrative sketches, not equivalent views of a fully specified system. The second deliberately leaves out authentication, caching and the gateway. Those need to appear in another view if they're relevant to the reader's question. A full ",(0,n.jsx)(t.a,{href:"https://c4model.com/diagrams/container",children:"C4 container diagram"})," would also show the system boundary, major technology choices and how the applications and data stores communicate."]}),"\n",(0,n.jsx)(t.p,{children:"Removing detail is useful only if the remaining picture still answers the question accurately."}),"\n",(0,n.jsx)(t.h2,{id:"give-ai-tools-the-same-brief",children:"Give AI tools the same brief"}),"\n",(0,n.jsx)(t.p,{children:"AI tools can make the arrows problem worse. Ask for an architecture diagram without saying who it's for or what it needs to explain, and you can end up with every import, function call and database relationship the tool can find."}),"\n",(0,n.jsx)(t.p,{children:"That might help you investigate dependencies. It won't necessarily help a new team member understand the system."}),"\n",(0,n.jsx)(t.p,{children:"Tell the tool the audience, the question and the level of detail. Review what it leaves out as carefully as what it includes. Access to the code doesn't tell it which relationships matter for this particular explanation."}),"\n",(0,n.jsx)(t.p,{children:"I prefer top-down layouts because I find them easier to scan. But layout comes after scope. Neatly arranging too much detail still leaves you with too much detail."}),"\n",(0,n.jsx)(t.p,{children:"The test I use: can someone new to the team look at the diagram and explain the part of the system it covers, without me hovering over their shoulder narrating? If they need me to explain the diagram first, I've drawn a very expensive set of notes."})]})}function c(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},5589(e,t,a){a.d(t,{R:()=>s,x:()=>o});var i=a(758);const n={},r=i.createContext(n);function s(e){const t=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:s(e.components),i.createElement(r.Provider,{value:t},e.children)}},3102(e){e.exports=JSON.parse('{"permalink":"/the-art-of-the-architecture-diagram-is-knowing-what-to-leave-out","source":"@site/blog/the-art-of-the-architecture-diagram-is-knowing-what-to-leave-out.md","title":"What to leave out of an architecture diagram","description":"There\'s a particular type of diagram that engineers love producing and nobody can read. Boxes for every service, arrows for every dependency, and a legend that requires its own legend. The details may all be accurate, but you still can\'t tell what the system does.","date":"2026-05-21T07:00:00.000Z","tags":[{"inline":true,"label":"architecture","permalink":"/tags/architecture"},{"inline":true,"label":"diagrams","permalink":"/tags/diagrams"},{"inline":true,"label":"c4","permalink":"/tags/c-4"},{"inline":true,"label":"d2","permalink":"/tags/d-2"}],"readingTime":3.13,"hasTruncateMarker":true,"authors":[{"name":"Danish Javed","title":"Software Engineer","url":"https://github.com/ambersariya","imageURL":"https://avatars.githubusercontent.com/u/1080238?s=400&u=5d6212c54765773934d34b3e55908846c9cd4a42&v=4","key":"ambersariya","page":null}],"frontMatter":{"title":"What to leave out of an architecture diagram","slug":"the-art-of-the-architecture-diagram-is-knowing-what-to-leave-out","date":"2026-05-21T07:00:00.000Z","authors":["ambersariya"],"tags":["architecture","diagrams","c4","d2"],"last_updated":"2026-11-20T10:31:14.000Z"},"unlisted":false,"prevItem":{"title":"Why we removed Docling","permalink":"/we-spent-five-weeks-making-docling-work-then-we-deleted-it"},"nextItem":{"title":"Enforcing architecture rules in CI","permalink":"/your-codebase-has-rules-does-ci-know-that"}}')}}]);